export const tournamentCopy = { en, ka } as const satisfies Record<Locale, object>;

export function fillTemplate(value: string, replacements: Record<string, string | number>) {
  return value.replace(/\{(\w+)\}/g, (match, key) => replacements[key] === undefined ? match : String(replacements[key]));
}

export function tournamentStatus(locale: Locale, status: string) {
  const statuses = tournamentCopy[locale].common.statuses as Record<string, string>;
  return statuses[status] ?? status.replaceAll('_', ' ').toLowerCase();
}

export function tournamentRound(locale: Locale, round: string) {
  const rounds = tournamentCopy[locale].common.rounds as Record<string, string>;
  return rounds[round] ?? round.replaceAll('_', ' ').toLowerCase();
}
